-- ── Leçon 9 : Gérer les risques financiers ──
INSERT INTO sms_lessons (course_id, title, type, points, order_index, content)
SELECT id, 'Gérer les risques : maladies, sécheresse, vol', 'notebook', 20, 9,
'{"cells": [
  {"type": "md", "content": "## Les risques qui ruinent les paysans\n\n**Durée** : 2h30 | **Matériel** : cartes illustrées des risques, graines, 3 boîtes (prévention, atténuation, transfert)\n\n### Activité : le classement des risques\n\n1. Distribuez des cartes illustrées : sécheresse, inondation, maladie de la famille, maladie des cultures, vol, décès d''un bœuf, chute des prix, incendie du grenier\n2. Le groupe classe les risques : « Quel est le PLUS fréquent ? Le plus GRAVE ? »\n3. Pour chaque risque, demandez : « Est-ce qu''on peut l''éviter ? Le réduire ? Le partager ? »"},
  {"type": "callout", "variant": "real", "title": "L''histoire de Moussa", "content": "Moussa, agriculteur au Burkina Faso, avait économisé 200 000 FCFA pour acheter un bœuf de trait. Son fils est tombé malade du paludisme. En une semaine, toute l''épargne a été dépensée en soins médicaux. Plus de bœuf, campagne ratée. Sans fonds d''urgence séparé, UN événement peut effacer des ANNÉES d''efforts."},
  {"type": "md", "content": "## Les 3 stratégies de gestion des risques\n\n| Stratégie | Exemple concret | Coût |\n|---|---|---|\n| **Prévenir** | Diversifier les cultures, variétés résistantes | Faible |\n| **Atténuer** | Fonds d''urgence (= épargne séparée pour les coups durs) | Moyen |\n| **Transférer** | Assurance récolte, mutuelle de santé, fonds social de l''AVEC | Variable |\n\n### Le fonds d''urgence : la priorité n°1\n\nAvant même d''épargner pour les intrants, chaque ménage devrait constituer un **fonds d''urgence** équivalent à 2-3 mois de dépenses alimentaires. C''est le matelas qui empêche de basculer."},
  {"type": "embed", "title": "Notebook live : impact d''un choc AVEC et SANS fonds d''urgence", "code": "print(\"SCENARIO : maladie grave dans la famille\")\nprint(\"Cout des soins : 150 000 FCFA\\n\")\n\nprint(\"--- SANS fonds d urgence ---\")\nepargne_intrants = 80000\nprint(f\"Epargne intrants disponible : {epargne_intrants:,} FCFA\")\nprint(f\"Le paysan utilise son epargne intrants : -{epargne_intrants:,}\")\nreste_a_payer = 150000 - epargne_intrants\nprint(f\"Reste a payer : {reste_a_payer:,} FCFA -> emprunt au commercant\")\nprint(f\"Consequence : pas d intrants -> campagne ratee -> dette\")\nprint(f\"Perte estimee sur l annee : ~300 000 FCFA\\n\")\n\nprint(\"--- AVEC fonds d urgence de 150 000 FCFA ---\")\nfonds_urgence = 150000\nprint(f\"Fonds d urgence : {fonds_urgence:,} FCFA\")\nprint(f\"Soins payes par le fonds : -{150000:,}\")\nprint(f\"Epargne intrants INTACTE : {epargne_intrants:,} FCFA\")\nprint(f\"Campagne normale -> revenus normaux\")\nprint(f\"\\nDifference : ~300 000 FCFA de revenus preserves\")\nprint(f\"Le fonds d urgence a RAPPORTE 300 000 FCFA !\")\n"},
  {"type": "callout", "variant": "tip", "title": "Facilitation : les 3 boîtes", "content": "Apportez 3 boîtes étiquetées : INTRANTS, URGENCE, FAMILLE. Avec des graines, montrez au groupe comment répartir les revenus de la récolte dans 3 enveloppes différentes. C''est la méthode des enveloppes — simple, visuelle, applicable immédiatement."},
  {"type": "quiz", "question": "Pourquoi le fonds d''urgence doit-il être SÉPARÉ de l''épargne pour les intrants ?", "opts": ["Pour compliquer les choses", "Pour éviter qu''un imprévu détruise la campagne agricole en entamant l''épargne productive", "Pour gagner plus d''intérêts", "Ce n''est pas nécessaire"], "ans": 1}
]}'::jsonb
FROM sms_courses WHERE code = 'TOF-FIN-01';

-- ── Leçon 10 : Structurer une session de formation ──
INSERT INTO sms_lessons (course_id, title, type, points, order_index, content)
SELECT id, 'Structurer et animer une session de formation au village', 'notebook', 25, 10,
'{"cells": [
  {"type": "md", "content": "## Le plan de session APCA : le canevas du formateur rural\n\nChaque session que vous animez au village doit suivre le cycle **APCA** :\n\n1. **A**ccroche (15 min) — Un problème vécu, une histoire, une question provocante\n2. **P**ratique (60 min) — Activité participative (cailloux, jeu de rôle, calcul collectif)\n3. **C**onceptualisation (20 min) — Le groupe formule la leçon apprise (PAS le formateur)\n4. **A**ction (15 min) — Engagement concret à appliquer avant la prochaine session\n\nDurée totale : **2h maximum**. Au-delà, les adultes en milieu rural décrochent (ils ont des champs à cultiver)."},
  {"type": "callout", "variant": "real", "title": "Pourquoi APCA et pas un cours classique ?", "content": "La recherche en andragogie (Kolb, Knowles, Freire) montre que les adultes retiennent 20% de ce qu''ils entendent, 50% de ce qu''ils voient, mais 80% de ce qu''ils FONT. Le cycle APCA met la PRATIQUE au centre. Le formateur parle 20% du temps, le groupe fait 80%."},
  {"type": "md", "content": "## Exemple : session sur le budget familial\n\n| Phase | Durée | Le formateur fait | Les participants font |\n|---|---|---|---|\n| **Accroche** | 15 min | Raconte l''histoire de Mamadou qui n''a plus d''argent en mars | Réagissent, s''identifient |\n| **Pratique** | 60 min | Distribue les graines, guide l''exercice | Construisent LEUR budget en graines |\n| **Conceptualisation** | 20 min | Pose la question : « Qu''avez-vous découvert ? » | Formulent : « On dépense plus qu''on ne gagne pendant 7 mois » |\n| **Action** | 15 min | « Que comptez-vous faire d''ici la prochaine session ? » | S''engagent : « Je vais calculer mon budget avec ma femme » |"},
  {"type": "embed", "title": "Notebook live : planifier un cycle de 12 sessions", "code": "sessions = [\n    (1, \"Mois 1 - S1\", \"D ou vient et ou va l argent ?\", \"Cailloux entrants/sortants\"),\n    (2, \"Mois 1 - S2\", \"Mon budget familial en graines\", \"12 tas + graines maïs/haricots\"),\n    (3, \"Mois 1 - S3\", \"L epargne : ou je garde mon argent ?\", \"Classement des formes d epargne\"),\n    (4, \"Mois 1 - S4\", \"La tontine et l AVEC\", \"Simulation tontine en cercle\"),\n    (5, \"Mois 2 - S5\", \"Combien me coute mon champ ?\", \"Calcul cout de production\"),\n    (6, \"Mois 2 - S6\", \"Planifier ma campagne\", \"Corde des saisons + tresorerie\"),\n    (7, \"Mois 2 - S7\", \"Le credit : opportunite ou piege ?\", \"Jeu de role 3 preteurs\"),\n    (8, \"Mois 2 - S8\", \"Vendre au bon moment\", \"Courbe des prix au sol\"),\n    (9, \"Mois 3 - S9\", \"Les risques et le fonds d urgence\", \"3 boites / methode enveloppes\"),\n    (10, \"Mois 3 - S10\", \"Structurer ma session de formation\", \"Preparer une fiche APCA\"),\n    (11, \"Mois 3 - S11\", \"Animer ma premiere session (pratique)\", \"Chaque stagiaire anime 20 min\"),\n    (12, \"Mois 3 - S12\", \"Bilan et plan d action communautaire\", \"Engagement collectif du village\"),\n]\nprint(\"PARCOURS DE FORMATION — 12 sessions sur 3 mois\")\nprint(f\"{'#':>2} {'Periode':<14} {'Theme':<42} {'Activite pratique'}\")\nprint(\"-\" * 95)\nfor n, p, t, a in sessions:\n    print(f\"{n:>2} {p:<14} {t:<42} {a}\")\nprint(f\"\\nTotal : {len(sessions)} sessions x 2h = 24 heures de formation\")\n"},
  {"type": "callout", "variant": "tip", "title": "La fiche de session : votre outil indispensable", "content": "Pour CHAQUE session, préparez une fiche A4 recto-verso : objectif, matériel nécessaire, déroulement APCA minute par minute, questions de facilitation, et la SEULE chose à retenir. Cette fiche, vous la donnez aux formateurs que vous formez. C''est l''outil de démultiplication."},
  {"type": "quiz", "question": "Dans le cycle APCA, à quel moment le formateur parle-t-il le plus ?", "opts": ["Pendant l''Accroche", "Pendant la Pratique", "Nulle part — le formateur parle 20% du temps maximum, le groupe fait 80%", "Pendant la Conceptualisation"], "ans": 2}
]}'::jsonb
FROM sms_courses WHERE code = 'TOF-FIN-01';

-- ── Leçon 11 : Pratique — animer sa première session ──
INSERT INTO sms_lessons (course_id, title, type, points, order_index, content)
SELECT id, 'Pratique supervisée : animez votre première session', 'notebook', 25, 11,
'{"cells": [
  {"type": "md", "content": "## C''est à vous de jouer !\n\n**Durée** : 3h | **Format** : chaque stagiaire anime 20 minutes devant le groupe\n\n### Consignes\n\n1. Choisissez UN thème parmi les sessions 1 à 9\n2. Préparez votre fiche APCA (leçon 10)\n3. Animez 20 minutes devant vos co-stagiaires qui jouent le rôle des paysans\n4. Le groupe et le superviseur donnent un retour constructif\n\n### Grille d''observation (pour le superviseur et les pairs)\n\n| Critère | 1 (à améliorer) | 2 (correct) | 3 (excellent) |\n|---|---|---|---|\n| Le formateur pose des questions avant d''expliquer | Fait un cours magistral | Pose quelques questions | Le groupe parle 80% du temps |\n| Utilisation du matériel concret (cailloux, dessins) | Tout à l''oral | Un support utilisé | Activité pratique bien menée |\n| Langage simple, pas de jargon | Termes techniques | Quelques mots compliqués | Langue locale + français simple |\n| Gestion du temps (respect du cycle APCA) | Pas de structure | APCA approximatif | 4 phases bien gérées |\n| Bienveillance (pas de jugement, valorise les savoirs) | Corrige / impose | Neutre | Valorise activement les réponses |"},
  {"type": "callout", "variant": "real", "title": "L''erreur la plus fréquente", "content": "90% des stagiaires formateurs font la MÊME erreur lors de leur première animation : ils parlent trop et ne laissent pas assez le groupe réfléchir. C''est normal — on a tous été formés par le modèle scolaire (le maître parle, l''élève écoute). L''andragogie, c''est le contraire. Il faut PRATIQUER pour désapprendre."},
  {"type": "md", "content": "## Le feedback constructif : la méthode sandwich\n\nAprès chaque animation de 20 minutes :\n\n1. **Pain du haut** : « Ce que tu as bien fait... » (toujours commencer par le positif)\n2. **Garniture** : « Ce que tu pourrais améliorer... » (un seul point, le plus important)\n3. **Pain du bas** : « Ce que j''ai particulièrement apprécié... » (finir sur du positif)\n\nLe superviseur donne son feedback EN DERNIER, après les pairs. Pourquoi ? Pour que les stagiaires apprennent aussi à s''évaluer entre eux."},
  {"type": "embed", "title": "Notebook live : auto-évaluation du formateur", "code": "print(\"AUTO-EVALUATION DU FORMATEUR — apres votre session\")\nprint(\"=\" * 50)\ncriteres = [\n    \"J ai laisse le groupe parler au moins 80% du temps\",\n    \"J ai utilise du materiel concret (cailloux, dessins)\",\n    \"J ai commence par un probleme vecu (Accroche)\",\n    \"J ai pose des questions au lieu d expliquer\",\n    \"J ai laisse le groupe formuler la lecon (Conceptualisation)\",\n    \"J ai propose un engagement concret (Action)\",\n    \"J ai parle en langue accessible (pas de jargon)\",\n    \"J ai respecte le temps (2h maximum)\",\n]\nprint(\"\\nRepondez OUI ou NON a chaque critere :\\n\")\nscore = 0\nfor i, c in enumerate(criteres, 1):\n    # Simulation : score aleatoire pour l''exemple\n    reponse = \"OUI\" if i % 3 != 0 else \"NON\"\n    score += 1 if reponse == \"OUI\" else 0\n    print(f\"  {i}. {c}\")\n    print(f\"     -> {reponse}\")\n\nprint(f\"\\nScore : {score}/{len(criteres)}\")\nif score >= 7: print(\"Excellent ! Vous etes pret(e) a animer au village.\")\nelif score >= 5: print(\"Bien ! Travaillez les points faibles avant le terrain.\")\nelse: print(\"Refaites une session d entrainement avec un pair.\")\n"},
  {"type": "quiz", "question": "Lors du feedback à un stagiaire, par quoi commencez-vous ?", "opts": ["Par les erreurs à corriger", "Par ce qu''il a bien fait (méthode sandwich)", "Par une note chiffrée", "Par un silence"], "ans": 1}
]}'::jsonb
FROM sms_courses WHERE code = 'TOF-FIN-01';

-- ── Leçon 12 : Capstone — Plan d'action communautaire ──
INSERT INTO sms_lessons (course_id, title, type, points, order_index, content)
SELECT id, 'Capstone : votre plan d''action communautaire', 'notebook', 30, 12,
'{"cells": [
  {"type": "md", "content": "## Bilan et engagement : que va changer ce parcours ?\n\n**Durée** : 3h | **Format** : atelier collectif de planification\n\n### Ce que vous maîtrisez maintenant\n\nEn 3 mois, vous avez appris à :\n\n- ✅ Adopter la posture de facilitateur (pas de professeur)\n- ✅ Animer le diagnostic financier participatif (cailloux, graines)\n- ✅ Accompagner la construction du budget familial\n- ✅ Expliquer l''épargne, la tontine, l''AVEC\n- ✅ Calculer le coût de production avec les paysans\n- ✅ Planifier la campagne agricole (corde des saisons)\n- ✅ Comparer les options de crédit (jeu de rôle)\n- ✅ Enseigner les stratégies de commercialisation\n- ✅ Mettre en place un fonds d''urgence (méthode des enveloppes)\n- ✅ Structurer une session APCA et animer avec confiance"},
  {"type": "callout", "variant": "real", "title": "L''impact réel de cette formation", "content": "Au Bénin, un programme similaire de formation de formateurs en gestion financière paysanne a touché 45 formateurs, qui ont chacun formé 4 groupes de 25 paysans. Résultat : 4 500 ménages touchés, avec en moyenne +35% d''épargne et -40% de recours au crédit du commerçant après 1 an. Vous êtes le premier maillon de cette chaîne."},
  {"type": "md", "content": "## Activité finale : le plan d''action communautaire\n\n### Chaque formateur remplit son plan :\n\n1. **Où** : dans quel(s) village(s) allez-vous intervenir ?\n2. **Quand** : dates des 12 sessions (un calendrier réaliste)\n3. **Qui** : combien de groupes ? Combien de participants par groupe ?\n4. **Comment** : quel matériel avez-vous besoin ? (graines, cordes, images)\n5. **Suivi** : comment mesurerez-vous le changement ? (avant/après)\n\n### Le tableau de suivi\n\n| Indicateur | Avant formation | Après 6 mois | Objectif |\n|---|---|---|---|\n| % de ménages avec un budget | à mesurer | à mesurer | 60% |\n| Épargne moyenne mensuelle | à mesurer | à mesurer | +30% |\n| % utilisant le crédit commerçant | à mesurer | à mesurer | -50% |\n| Nb de tontines/AVEC actives | à compter | à compter | +3 |"},
  {"type": "embed", "title": "Notebook live : projeter l''impact de votre formation", "code": "print(\"PROJECTION D IMPACT — Votre plan de formation\")\nprint(\"=\" * 55)\n\nnb_formateurs = 1  # vous\ngroupes_par_formateur = 4\npaysans_par_groupe = 25\ntotal_paysans = nb_formateurs * groupes_par_formateur * paysans_par_groupe\npersonnes_par_menage = 7  # moyenne Afrique de l Ouest\ntotal_beneficiaires = total_paysans * personnes_par_menage\n\nprint(f\"Formateurs formes       : {nb_formateurs}\")\nprint(f\"Groupes a former        : {groupes_par_formateur}\")\nprint(f\"Paysans par groupe      : {paysans_par_groupe}\")\nprint(f\"Total paysans touches   : {total_paysans}\")\nprint(f\"Beneficiaires indirects : {total_beneficiaires} personnes\")\nprint(f\"                          (menages de {personnes_par_menage} personnes)\")\n\nprint(f\"\\n--- Si chaque paysan forme a son tour forme 2 voisins ---\")\neffet_boule = total_paysans * 2\nprint(f\"Effet boule de neige    : +{effet_boule} paysans supplementaires\")\nprint(f\"Impact total possible   : {(total_paysans + effet_boule) * personnes_par_menage:,} personnes\")\n\nprint(f\"\\n--- Impact financier estime ---\")\nepargne_moyenne = 16000  # FCFA/mois\nepargne_annuelle = epargne_moyenne * 12 * total_paysans\nprint(f\"Si chaque paysan epargne {epargne_moyenne:,} FCFA/mois\")\nprint(f\"Epargne collective annuelle : {epargne_annuelle:,} FCFA\")\nprint(f\"Soit {epargne_annuelle // 655:,} euros mobilises dans la communaute\")\n"},
  {"type": "md", "content": "## La certification\n\nPour obtenir votre **attestation de Formateur en Gestion Financière Paysanne**, vous devez :\n\n1. ✅ Avoir suivi les 12 sessions (présence)\n2. ✅ Avoir réussi les quiz (score ≥ 70%)\n3. ✅ Avoir animé une session supervisée (leçon 11, note ≥ 2/3 sur chaque critère)\n4. ✅ Avoir remis votre plan d''action communautaire\n\nDemandez votre attestation depuis votre tableau de bord étudiant !"},
  {"type": "callout", "variant": "real", "title": "Vous êtes maintenant formateur", "content": "Vous faites partie d''un réseau de formateurs ruraux en gestion financière. Votre mission : aller dans les villages, écouter les paysans, et les accompagner vers une meilleure maîtrise de leur argent. Pas avec des théories, mais avec des cailloux, des graines, des histoires vraies et beaucoup d''écoute. Bon terrain !"},
  {"type": "resource", "title": "Kit du formateur rural (outils GRAAP)", "url": "https://www.yourcentre.org/", "provider": "GRAAP / Réseau andragogique", "desc": "Guides visuels, images grand format, et méthodologies d''animation participative pour formateurs en milieu rural africain."},
  {"type": "resource", "title": "Guide VSLA — Village Savings and Loan Associations", "url": "https://www.vsla.net/", "provider": "CARE International", "desc": "Le guide méthodologique complet pour créer et accompagner des groupes d''épargne villageois (AVEC/VSLA). Gratuit, traduit en français."},
  {"type": "quiz", "question": "Vous avez formé 4 groupes de 25 paysans. Chacun forme 2 voisins. Combien de personnes sont touchées au total (paysans directs + effet boule de neige) ?", "opts": ["100 paysans", "200 paysans", "300 paysans (100 directs + 200 par effet boule de neige)", "500 paysans"], "ans": 2}
]}'::jsonb
FROM sms_courses WHERE code = 'TOF-FIN-01';
